function shell(){document.documentElement.lang=state.lang;$('#app').innerHTML=`<header class="top"><div class="container toprow"><a class="brand" href="#home"><em>S</em>Stołownik<span>ATLAS</span></a><nav>${T('nav').map((x,i)=>`<a href="#${['catalog','living','training','restaurant','explore'][i]}">${x}</a>`).join('')}<a href="#world">Świat</a><a href="#market">Kraje i sklepy</a></nav><select id="lang" aria-label="Language"><option value="pl">PL</option><option value="en">EN</option><option value="de">DE</option><option value="es">ES</option><option value="fr">FR</option><option value="it">IT</option><option value="pt">PT</option><option value="uk">UK</option></select><button class="btn ghost" style="color:white;border-color:#ffffff70" data-do="account">Moja przestrzeń</button></div></header><main><section class="hero" id="home"><div class="container heroGrid"><div><span class="eyebrow">FOOD · CULTURE · MOVEMENT</span><h1 class="display">${state.lang==='pl'?`Smak ma swój <i>świat.</i>`:E(T('hero'))}</h1><p>${T('intro')}</p><div class="heroActions"><a class="btn lime" href="#catalog">${T('discover')} ↗</a><button class="btn ghost" style="color:white;border-color:#ffffff80" data-do="plan">${T('plan')}</button></div><div class="heroTrust"><span>✓ Fotografia przypisana do dania w źródle</span><span>✓ Podpis źródła przy przepisach zewnętrznych</span><span>✓ Bez wymyślonych kalorii</span></div></div><div class="heroPhotoWrap"><img class="heroPhoto" src="${image(sample)}" alt="Spicy Arrabiata Penne, zdjęcie dania z TheMealDB"><div class="heroBadge"><b>Spicy Arrabiata Penne</b><small>Włochy · <a href="${recipeUrl(sample)}" target="_blank" rel="noopener">TheMealDB ↗</a></small></div></div></div></section><div class="container"><div class="ribbon"><button data-do="catalog"><span class="mark">✳</span><strong>Kuchnie świata</strong><small>Przepisy ze źródłami →</small></button><button data-do="plan"><span class="mark">▦</span><strong>Plan tygodnia</strong><small>Od pomysłu do zakupów →</small></button><button data-do="training"><span class="mark">↗</span><strong>Forma i ruch</strong><small>Prosty plan treningowy →</small></button><button data-do="restaurant"><span class="mark">◫</span><strong>Restauracja</strong><small>Menu i koszt porcji →</small></button></div></div><section class="section worldSection" id="world"><div class="container"><div class="sectionHead"><div><span class="eyebrow">STOŁOWNIK / WORLD</span><h2 class="display">Podróżuj przez smaki.</h2></div><p>Lista nazw kuchni i regionów pochodzi ze źródła; obecność na liście nie gwarantuje dostępnych przepisów. Wybierz region, aby to sprawdzić.</p></div><div class="worldBar"><div class="passport"><span>◎ MÓJ PASZPORT SMAKÓW</span><strong id="passportCount">0</strong><small>odkrytych kuchni i regionów</small><button class="btn ghost" data-do="passport">Otwórz paszport ↗</button></div><div class="worldSearch"><h3>Zacznij od składnika.</h3><p>Źródło wyszukuje jeden główny składnik naraz. Wpisz nazwę polską lub angielską; wyniki pochodzą ze źródła.</p><form id="ingredientForm" class="row"><input id="ingredient" placeholder="np. chicken, tomato, rice" required aria-label="Składnik po angielsku"><button class="btn">Szukaj przepisów</button></form><small>Wynik zależy od zawartości bazy źródłowej.</small></div></div><div class="worldTitle"><h3>Kuchnie i regiony</h3><input id="areaQuery" type="search" placeholder="Filtruj listę kuchni…" aria-label="Filtruj kuchnie"></div><p id="worldSummary" class="fine"></p><div class="worldGrid" id="worldGrid"></div><div class="heritageHead"><span class="eyebrow">KONTEKST KULTUROWY</span><h3>Jedzenie to także tradycja.</h3><p>Historie opisane przez UNESCO. Odkrywaj źródła, a potem szukaj powiązanych dań w katalogu.</p></div><div class="heritage"><article><span>01 / JAPONIA</span><h4>Washoku</h4><p>Tradycyjna kultura żywieniowa Japonii obejmuje wiedzę i zwyczaje związane z przygotowaniem i spożywaniem posiłków.</p><a href="https://ich.unesco.org/en/RL/washoku-traditional-dietary-cultures-of-the-japanese-notably-for-the-celebration-of-new-year-00869" target="_blank" rel="noopener">Zobacz źródło UNESCO ↗</a></article><article><span>02 / ŚRÓDZIEMNOMORZE</span><h4>Dieta śródziemnomorska</h4><p>UNESCO opisuje ją jako zbiór umiejętności, zwyczajów i tradycji dotyczących jedzenia oraz wspólnego stołu.</p><a href="https://ich.unesco.org/en/RL/mediterranean-diet-00884" target="_blank" rel="noopener">Zobacz źródło UNESCO ↗</a></article><article><span>03 / NEAPOL</span><h4>Sztuka pizzaiuolo</h4><p>Praktyka neapolitańskich pizzaiuoli obejmuje przygotowanie ciasta i wypiek pizzy.</p><a href="https://ich.unesco.org/en/RL/art-of-neapolitan-pizzaiuolo-00722" target="_blank" rel="noopener">Zobacz źródło UNESCO ↗</a></article></div></div></section><section class="section" id="catalog"><div class="container"><div class="sectionHead"><div><span class="eyebrow">ATLAS SMAKÓW</span><h2 class="display">${T('catalog')}</h2></div><p>${T('detail')}</p></div><form class="filterRow" id="searchForm"><input id="search" aria-label="Szukaj dań" placeholder="${E(T('search'))}" autocomplete="off"><select id="category" aria-label="Kategoria"><option value="">Kategoria</option>${['Vegetarian','Vegan','Pasta','Seafood','Chicken','Beef','Dessert','Starter','Miscellaneous'].map(x=>`<option>${x}</option>`).join('')}</select><select id="area" aria-label="Kuchnia"><option value="">Kuchnia świata</option>${['Italian','Mexican','Indian','Japanese','French','British','American','Thai','Chinese','Greek','Turkish','Polish'].map(x=>`<option>${x}</option>`).join('')}</select><button class="btn">Szukaj</button></form><form id="letterForm" class="letterForm"><label for="letter">Odkrywaj po pierwszej literze</label><select id="letter" aria-label="Pierwsza litera nazwy po angielsku">${Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ').map(x=>`<option>${x}</option>`).join('')}</select><button class="btn silent">Pokaż źródłowe dania</button></form><div class="tabs"><button class="active" data-tab="browse">Odkrywaj</button><button data-do="desserts">Desery</button><button data-do="drinks">Napoje bezalkoholowe</button><button data-tab="favorites">♥ Ulubione</button><button data-tab="mine">Moje przepisy</button><button data-do="random">✧ Losuj</button></div><div class="statusLine"><span id="count"></span><span>Źródła: <a href="https://www.themealdb.com/" target="_blank" rel="noopener">TheMealDB ↗</a> · <a href="https://www.thecocktaildb.com/" target="_blank" rel="noopener">TheCocktailDB ↗</a></span></div><div class="recipes" id="grid"></div><button class="btn ghost" style="display:block;margin:25px auto 0" data-do="next">Pokaż więcej ↓</button></div></section><section class="section sectionAlt" id="living"><div class="container"><div class="sectionHead"><div><span class="eyebrow">ZAPLANUJ PO SWOJEMU</span><h2 class="display">Dobrze jeść. Łatwiej żyć.</h2></div><p>Twój plan i zakupy działają bez konta, na tym urządzeniu. Możesz je wyeksportować.</p></div><div class="featureGrid"><article class="feature lime"><span class="eyebrow" style="color:#315332">01 / TYGODNIOWY RYTM</span><h3>Smaczny plan na tydzień</h3><p>Zapisz przepisy na wybrane dni i zamień składniki w listę zakupów.</p><div class="row"><button class="btn" data-do="plan">Otwórz planer ↗</button><button class="btn ghost" data-do="pantry">Moja spiżarnia ↗</button></div></article><article class="feature"><span class="eyebrow">02 / KUCHNIA W PRAKTYCE</span><h3>Zakupy bez chaosu</h3><p>Dodawaj składniki z receptur i własne produkty. Zaznaczaj to, co już masz.</p><button class="btn ghost" data-do="shopping">Otwórz listę ↗</button></article></div></div></section><section class="section sectionAlt" id="ingredients"><div class="container"><div class="sectionHead"><div><span class="eyebrow">ATLAS / SKŁADNIKI</span><h2 class="display">Składniki z prawdziwych rekordów.</h2></div><p>Wyszukaj składnik i przejdź do dań, w których występuje. Wyniki pochodzą z katalogu TheMealDB i legalnie dodanych receptur; liczba oznacza tylko załadowane nazwy.</p></div><label for="ingredientLookup">Szukaj składnika</label><input id="ingredientLookup" type="search" maxlength="80" placeholder="np. lemon, rice, milk" aria-controls="ingredientGrid"><p id="ingredientCount" class="muted" aria-live="polite"></p><div id="ingredientGrid" class="ingredientGrid"></div><p class="fine">Nazwy zachowują język źródła. Produkty marek, ich składy i alergeny wymagają sprawdzenia na etykiecie. Źródło listy: <a href="https://www.themealdb.com/" target="_blank" rel="noopener">TheMealDB ↗</a>.</p></div></section><section class="section marketSection" id="market"><div class="container"><div class="sectionHead"><div><span class="eyebrow">ATLAS / LOCAL</span><h2 class="display">Twój kraj. Twoje zakupy.</h2></div><p>Ustaw rynek dla waluty własnego budżetu i otwórz wyszukiwanie produktów lub sklepów w zewnętrznym serwisie. Bez fikcyjnych cen.</p></div><div class="marketLayout"><div class="marketPanel"><label>Kraj i waluta<select id="marketSelect">${MARKETS.map(x=>`<option value="${x[0]}">${x[1]} · ${x[2]}</option>`).join('')}</select></label><p>Wspierane rynki: ${MARKETS.length}. Poza nimi możesz wyszukać sklep w dowolnym miejscu, wpisując własny kraj lub miasto.</p><button class="btn" data-do="shopping">Moja lista i budżet ↗</button></div><div class="marketPanel pale"><h3>Znajdź produkt</h3><form id="storeForm"><input id="storeProduct" maxlength="100" placeholder="np. ryż basmati" required aria-label="Produkt"><input id="storePlace" maxlength="100" placeholder="Miasto lub kraj (opcjonalnie)" aria-label="Miejsce"><div class="row"><button class="btn" type="button" data-do="storeWeb">Szukaj ofert ↗</button><button class="btn ghost" type="button" data-do="storeMap">Sklepy na mapie ↗</button></div></form><small>Linki prowadzą do wyników Google i Map. Stołownik nie jest partnerem tych sklepów i nie pobiera ofert ani cen.</small></div></div><div class="partnerStrip"><div><span class="eyebrow">PARTNERSTWA</span><h3>Przestrzeń dla przyszłych partnerów.</h3><p>Firmy i produkty można będzie pokazać dopiero po zawarciu współpracy oraz oznaczeniu materiałów promocyjnych.</p></div><button class="btn ghost" data-do="partner">Zasady partnerstw ↗</button></div></div></section><section class="section" id="training"><div class="container"><div class="sectionHead"><div><span class="eyebrow">FORMA PO TWOJEMU</span><h2 class="display">Siła zaczyna się od planu.</h2></div><p>Wybierz cel i miejsce treningu. Szablon daje punkt wyjścia do regularnego ruchu.</p></div><div class="featureGrid"><article class="feature dark"><span class="eyebrow">ATLAS / RUCH</span><h3>Trening siłowy dopasowany do celu</h3><p>Siła, mięśnie, redukcja lub ogólna sprawność. Dwa do czterech dni i warianty domowe.</p><button class="btn lime" data-do="training">Ułóż trening ↗</button></article><article class="feature"><span class="eyebrow">ZASADY</span><h3>Bez fałszywej precyzji</h3><p>Nie wyliczamy kalorii ani obietnic zmiany masy bez danych i opieki specjalisty. Ruch możesz połączyć z własnym planem posiłków.</p><a class="btn ghost" href="https://www.who.int/initiatives/behealthy/physical-activity" target="_blank" rel="noopener">Zalecenia WHO ↗</a></article></div></div></section><section class="section sectionAlt" id="restaurant"><div class="container"><div class="sectionHead"><div><span class="eyebrow">GASTRONOMIA</span><h2 class="display">Z pomysłu do karty dań.</h2></div><p>Przelicz koszt składników, porcji i cenę menu na podstawie własnych danych.</p></div><article class="feature dark"><h3>Twoja pracownia restauracji</h3><p>Menu, koszt porcji, food cost i cena. Wszystkie obliczenia lokalne, bez udawania aktualnych cen sklepów.</p><div class="row"><button class="btn lime" data-do="restaurant">Kalkulator menu ↗</button><button class="btn" data-do="venture">Projekt restauracji ↗</button></div></article></div></section><section class="section" id="explore"><div class="container"><div class="sectionHead"><div><span class="eyebrow">ROZWIJAJ ATLAS</span><h2 class="display">Narzędzia na dobry początek.</h2></div></div><div class="ecosystem"><button class="utility" data-do="addOwn"><span>✎</span><b>Własny przepis</b><small>Prywatna receptura zapisana lokalnie →</small></button><button class="utility" data-do="shopping"><span>▤</span><b>Zakupy</b><small>Składniki i odhaczanie produktów →</small></button><button class="utility" data-do="export"><span>↓</span><b>Kopia danych</b><small>Pobierz swoje planowanie i menu →</small></button><button class="utility" data-do="source"><span>◎</span><b>Źródła i zdjęcia</b><small>Dowiedz się, skąd pochodzą karty →</small></button><button class="utility" data-do="account"><span>♙</span><b>Konto / Premium</b><small>Stan przyszłych usług →</small></button><button class="utility" data-do="pantry"><span>◉</span><b>Moja spiżarnia</b><small>Pomysły z posiadanych składników →</small></button><button class="utility" data-do="venture"><span>◫</span><b>Projekt restauracji</b><small>Nazwa, koncepcja i menu →</small></button><button class="utility" data-do="journal"><span>▥</span><b>Dziennik treningowy</b><small>Zapisuj własny wysiłek i progres →</small></button><button class="utility" data-do="languageInfo"><span>◎</span><b>Języki interfejsu</b><small>Zakres tłumaczeń i teksty źródłowe →</small></button><button class="utility" data-do="market"><span>⌕</span><b>Rynki i sklepy</b><small>Produkty oraz sklepy w wybranym kraju →</small></button><button class="utility" data-do="quality"><span>✓</span><b>Jakość danych</b><small>Co sprawdzamy, czego nie zgadujemy →</small></button></div></div></section></main><footer class="footer"><div class="container footerGrid"><div><a class="brand" href="#home"><em>S</em>Stołownik<span>ATLAS</span></a><p>Nowa koncepcja od zera. Jedzenie, kultura i ruch w jednym miejscu.</p></div><div><b>Odkrywaj</b><p><a href="#catalog">Przepisy</a><br><a href="#living">Planer</a><br><a href="#training">Trening</a></p></div><div><b>Uczciwe źródła</b><p>Przepisy i zdjęcia: <a href="https://www.themealdb.com/" target="_blank" rel="noopener">TheMealDB</a>.<br>Aktywność: <a href="https://www.who.int/initiatives/behealthy/physical-activity" target="_blank" rel="noopener">WHO</a>.</p><small>Wersja rozwojowa · Dane użytkownika na tym urządzeniu</small></div></div></footer><div id="dialogRoot"></div>`;$('#lang').value=state.lang;$('#marketSelect').value=state.market;$('#marketSelect').onchange=e=>{state.market=e.target.value;put('market',state.market)};$('#storeForm').onsubmit=e=>{e.preventDefault();openStore('web')};$('#lang').onchange=e=>{state.lang=e.target.value;put('lang',state.lang);shell()};$('#searchForm').onsubmit=e=>{e.preventDefault();search()};$('#letterForm').onsubmit=e=>{e.preventDefault();browseLetter($('#letter').value)};$('#areaQuery').oninput=renderWorld;$('#ingredientForm').onsubmit=e=>{e.preventDefault();$('#search').value=$('#ingredient').value.trim();search().then(()=>location.hash='catalog')};$('#category').onchange=()=>browse('c',$('#category').value);$('#area').onchange=()=>browse('a',$('#area').value);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderGrid()});renderGrid();renderWorld();renderIngredients();loadAreas();$('#ingredientLookup').oninput=renderIngredients}
function cardAttribution(m){if(m.local)return '<small class="credit">Prywatny wpis użytkownika · bez publikacji</small>';if(m.bundled)return `<small class="credit">Przepis: ${m.sourceUrl?`<a href="${E(m.sourceUrl)}" target="_blank" rel="noopener">${E(m.sourceName||'źródło')}</a>`:'szczegóły'} · Zdjęcie: ${m.photoSourceUrl?`<a href="${E(m.photoSourceUrl)}" target="_blank" rel="noopener">${E(m.photoAuthor||'źródło zdjęcia')}</a>`:'szczegóły'}</small>`;return `<small class="credit">Przepis i zdjęcie: <a href="${recipeUrl(m)}" target="_blank" rel="noopener">${sourceLabel(m)} ↗</a></small>`}
function renderGrid(){const arr=state.tab==='favorites'?ids().filter(x=>state.favorites.includes(String(x.idMeal))):state.tab==='mine'?state.mine:state.bundledAll?.length?state.bundled:state.items;$('#count').textContent=state.loading?'Ładowanie receptur…':state.dataError?'Nie można potwierdzić liczby dań — błąd źródła':`${arr.length} ${T('results')}${state.tab==='browse'?' · liczba dotyczy odpowiedzi źródła, nie wszystkich dań świata':''}${state.searchNote?' · '+state.searchNote:''}`;$('#grid').innerHTML=arr.length?arr.slice(0,state.visible).map(m=>`<article class="recipe"><div class="visual">${image(m)?`<img src="${E(image(m))}" loading="lazy" alt="${E(m.strMeal)}">`:''}<span>${m.bundled?'Fotografia · '+E(m.photoAuthor||'autor w szczegółach'):m.local?'Twój przepis':'Fotografia · '+sourceLabel(m)}</span></div><div class="recipeBody"><div class="meta">${E(m.strArea|| (m.local?'Twoja kuchnia':'Region niepodany'))} · ${E(m.strCategory||'Przepis')}</div><h3>${E(m.strMeal)}</h3><p>${m.local?'Prywatny przepis':m.bundled?`Tekst: ${E(m.sourceName||'źródło w szczegółach')} · zdjęcie: ${E(m.photoAuthor||'autor w szczegółach')}`:'Tekst i zdjęcie: '+sourceLabel(m)}.</p>${cardAttribution(m)}<div class="actions"><button class="btn" data-do="open" data-id="${E(m.idMeal)}">Zobacz przepis</button><button class="heart" data-do="heart" data-id="${E(m.idMeal)}" aria-label="Zapisz przepis">${state.favorites.includes(String(m.idMeal))?'♥':'♡'}</button></div></div></article>`).join(''):`<div class="empty">${state.loading?'Trwa pobieranie…':state.dataError?'Nie udało się pobrać danych. Spróbuj ponownie.':state.tab==='favorites'?'Nie masz jeszcze zapisanych przepisów.':state.tab==='mine'?'Dodaj własny przepis w sekcji narzędzi.':'Nie znaleziono receptur w tym widoku.'}</div>`}
function renderIngredients(){const host=$('#ingredientGrid');if(!host)return;const fromRecipes=ids().flatMap(m=>m.ingredients||[]).map(i=>i.name).filter(Boolean);const available=[...new Set([...state.ingredientIndex,...fromRecipes].map(x=>String(x).trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));const q=($('#ingredientLookup')?.value||'').trim();const terms=q?queryTerms(q):[];const hits=available.filter(x=>!q||terms.some(t=>fold(x).includes(fold(t))));$('#ingredientCount').textContent=`${hits.length} pasujących · ${available.length} załadowanych nazw (${state.ingredientSource})`;host.innerHTML=hits.slice(0,48).map(x=>`<div class="ingredientTile"><b>${E(x)}</b><span><button class="btn ghost" data-do="ingredientBrowse" data-name="${E(x)}">Przepisy ↗</button><button class="btn silent" data-do="ingredientPantry" data-name="${E(x)}">+ Spiżarnia</button></span></div>`).join('')||'<p class="muted">Brak wyników w załadowanej liście.</p>';}
async function loadIngredients(){try{const d=await api('list.php?i=list');const list=(d.meals||[]).map(x=>x.strIngredient).filter(Boolean);if(list.length){state.ingredientIndex=list;state.ingredientSource='TheMealDB';renderIngredients()}}catch{state.ingredientIndex=ingredients(sample).map(i=>i.name);renderIngredients()}}
function renderWorld(){const host=$('#worldGrid');if(!host)return;const q=fold($('#areaQuery')?.value||'');$('#passportCount').textContent=state.visited.length;const highlights=['Italian','Mexican','Indian','Japanese','Thai','French','British','American','Greek','Turkish','Polish','Canadian'];const display=q?state.areas.filter(x=>fold(x).includes(q)).slice(0,36):highlights.filter(x=>state.areas.includes(x));host.innerHTML=display.map((x,i)=>`<button class="worldCard" data-do="worldArea" data-area="${E(x)}"><span>${String(i+1).padStart(2,'0')} / KUCHNIA W ŹRÓDLE</span><strong>${E(x)}</strong><small>${state.areaCounts[x]!=null?`${state.areaCounts[x]} dań w sprawdzonej odpowiedzi`:state.visited.includes(x)?'✓ Odkryto · sprawdź dania':'Sprawdź dostępne dania →'}</small></button>`).join('')||'<p>Brak regionu o tej nazwie na liście źródła.</p>';const summary=$('#worldSummary');if(summary)summary.textContent=q?`Pokazano ${display.length} z ${state.areas.length} nazw; wyniki ograniczone do 36.`:'Wybrane regiony. Wpisz nazwę, aby przeszukać pełną listę źródła.'}
async function loadAreas(){try{const d=await api('list.php?a=list');const a=(d.meals||[]).map(x=>x.strArea).filter(Boolean);if(a.length){state.areas=[...new Set(a)].sort((x,y)=>x.localeCompare(y));const select=$('#area');if(select)select.innerHTML='<option value="">Kuchnia / region</option>'+state.areas.map(x=>`<option value="${E(x)}">${E(x)}</option>`).join('');renderWorld()}}catch{}}
function passport(){dialog('Paszport smaków',`<p>Każdy region dodaje się po otwarciu receptury ze źródła. Lista zostaje na tym urządzeniu.</p>${state.visited.length?state.visited.map(x=>`<button class="btn silent" style="margin:4px" data-do="worldArea" data-area="${E(x)}">${E(x)} ↗</button>`).join(''):'<p class="muted">Otwórz przepis z dowolnej kuchni, aby zacząć.</p>'}<p class="fine">Nazwy pochodzą z pola regionu bazy receptur; nie oznaczają potwierdzenia autentyczności każdego dania.</p>`)}
async function api(path,base=API){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const r=await fetch(base+path,{signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}async function browse(k,v){if(!v)return;if(state.bundledAll?.length){state.bundled=state.bundledAll.filter(x=>k==='i'?x.ingredients.some(i=>i.name.toLocaleLowerCase().includes(v.toLocaleLowerCase())):(k==='c'?x.strCategory:x.strArea)===v);state.visible=24;state.tab='browse';document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='browse'));renderGrid();return}state.loading=true;state.dataError=false;state.searchNote='';renderGrid();let token=++state.request;try{const d=await api(`filter.php?${k}=${encodeURIComponent(v)}`);if(token!==state.request)return;state.items=d.meals||[];if(k==='a'){state.areaCounts[v]=state.items.length;renderWorld()}state.dataError=false;state.searchNote=`Kuchnia lub kategoria: ${v}. Liczba według odpowiedzi TheMealDB (wersja testowa API może ograniczać wyniki).`;state.items.forEach(x=>state.cache[x.idMeal]=x);state.tab='browse';document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='browse'))}catch(e){if(token===state.request){state.items=[];state.dataError=true;state.searchNote='Błąd źródła — brak potwierdzonej liczby wyników.'}}finally{if(token===state.request){state.loading=false;renderGrid()}}}
const aliases={krewetk:['shrimp','prawn'],kurczak:['chicken'],wolowin:['beef'],losos:['salmon'],ryz:['rice'],makaron:['pasta'],ziemniak:['potato'],ser:['cheese'],czekolad:['chocolate'],truskawk:['strawberry'],jablk:['apple'],zup:['soup'],mlek:['milk'],ciast:['cake'],deser:['dessert'],napoj:['drink'],koktajl:['cocktail'],ryb:['fish'],jajk:['egg'],grzyb:['mushroom']};
const fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l').toLocaleLowerCase().trim();
function queryTerms(q){const folded=fold(q);for(const [stem,terms] of Object.entries(aliases))if(folded.includes(stem))return terms;return [q.trim()]}
async function search(){const q=$('#search').value.trim();if(!q){browse('c','Vegetarian');return}const terms=queryTerms(q),token=++state.request;state.visible=24;state.loading=true;state.dataError=false;state.searchNote='';renderGrid();
 if(state.bundledAll?.length){state.bundled=state.bundledAll.filter(x=>fold([x.strMeal,x.strArea,x.strCategory,...x.ingredients.map(i=>i.name)].join(' ')).includes(fold(q))||terms.some(t=>fold([x.strMeal,x.strArea,x.strCategory,...x.ingredients.map(i=>i.name)].join(' ')).includes(fold(t))));state.tab='browse';state.loading=false;state.searchNote='Szukano w licencjonowanym katalogu lokalnym.';renderGrid();return}
 const requests=[...new Set(terms.flatMap(t=>['search.php?s='+encodeURIComponent(t),'filter.php?i='+encodeURIComponent(t)]))],drink=state.mode==='drinks';
 const results=await Promise.allSettled(requests.map(path=>api(path,drink?DRINK_API:API)));if(token!==state.request)return;const successes=results.filter(x=>x.status==='fulfilled').map(x=>x.value);const found=[...new Map(successes.flatMap(x=>drink?(x.drinks||[]).map(drinkRecord):(x.meals||[])).map(x=>[x.idMeal,x])).values()];
 if(successes.length){state.dataError=false;state.items=found;found.forEach(x=>state.cache[x.idMeal]=x);state.searchNote=`Zapytanie „${q}” → ${terms.join(', ')}. Wyniki z nazw i głównego składnika w ${drink?'TheCocktailDB':'TheMealDB'}; API może ograniczać liczbę odpowiedzi.`;state.tab='browse'}else{state.items=[];state.dataError=true;state.searchNote='Źródło jest chwilowo niedostępne. Liczba wyników jest nieznana.'}
 state.loading=false;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='browse'));renderGrid();}
async function loadShowcase(){state.loading=true;state.dataError=false;renderGrid();const token=++state.request;const cats=['Seafood','Dessert','Vegetarian'];const results=await Promise.allSettled(cats.map(c=>api('filter.php?c='+encodeURIComponent(c))));if(token!==state.request)return;const matches=results.map((x,i)=>x.status==='fulfilled'?(x.value.meals||[]).map(m=>({...m,strCategory:cats[i]})):[]);const found=[...new Map(matches.flat().map(m=>[m.idMeal,m])).values()];state.items=found;state.mode='meals';state.items.forEach(x=>state.cache[x.idMeal]=x);state.loading=false;state.dataError=!results.some(x=>x.status==='fulfilled');state.searchNote=state.dataError?'Nie można pobrać żadnej kategorii. Spróbuj ponownie.':`Wybrane kategorie: owoce morza, desery i wegetariańskie. ${results.filter(x=>x.status==='rejected').length?'Część źródeł nie odpowiedziała. ':''}Liczba to unikalne rekordy zwrócone przez API, z limitem na kategorię.`;renderGrid()}
async function browseLetter(letter){if(!/^[A-Z]$/.test(letter))return;state.loading=true;state.dataError=false;state.searchNote='';renderGrid();const token=++state.request;try{const d=await api('search.php?f='+letter.toLowerCase());if(token!==state.request)return;state.mode='meals';state.items=d.meals||[];state.items.forEach(x=>state.cache[x.idMeal]=x);state.tab='browse';state.searchNote=`Litera ${letter}: tylko dania zwrócone przez TheMealDB; limit wersji testowej API może ukrywać pozostałe.`}catch{if(token===state.request){state.items=[];state.dataError=true;state.searchNote='Nie udało się pobrać dań dla tej litery.'}}finally{if(token===state.request){state.loading=false;renderGrid()}}}
